package org.javaavance.exception.passwords;

public class LambdaPasswordValidator <T> {

    @FunctionalInterface
    interface Validator<T> {
        boolean checkRule(T t) throws CustomException;
    }
    private final Validator<T> validator;

    public LambdaPasswordValidator(Validator<T> validator) {
        this.validator = validator;
    }

    public LambdaPasswordValidator andThen(Validator<T> other) {
        Validator<T> combined = s -> validator.checkRule(s) && other.checkRule(s);
        return new LambdaPasswordValidator(combined);
    }

    // Minimum de taille 8
    static Validator<String> lengthRule = (pwd) -> {
        if (pwd == null || pwd.length() < 8) throw new LengthException(pwd);
        return true;
    };

    // Contient des lettres minuscules et majuscules
    static Validator<String> caseRule = (pwd) -> {
        if (!pwd.matches("^(?=.*[a-z])(?=.*[A-Z]).+$")) throw new LetterCaseException(pwd);
        return true;
    };

    // Contient au minimum 2 nombres
    static Validator<String> digitRule = (pwd) -> {
        long count = pwd.chars().filter(Character::isDigit).count();
        if (count < 2) throw new DigitCountException(pwd);
        return true;
    };

    static LambdaPasswordValidator<String> passwordValidator
            = new LambdaPasswordValidator<String>(lengthRule).andThen(caseRule).andThen(digitRule);

    public void checkRule(T t) throws CustomException {
        validator.checkRule(t);
    }

    public static void validatePassword(String password) throws CustomException {
        // Valide le mot de passe avec les règles
        passwordValidator.checkRule(password);
        System.out.println("Le mot de passe " + password + " est valide!");
    }

    public static void main(String[] args) {
        try {
            validatePassword(null);
        } catch (CustomException e) {
            System.err.println(e.getMessage());
        }
        try {
            validatePassword("weak123");
        } catch (CustomException e) {
            System.err.println(e.getMessage());
        }

        try {
            validatePassword("StrongPwd5");
        } catch (CustomException e) {
            System.err.println(e.getMessage());
        }

        try {
            validatePassword("StrongPwd45");
        } catch (CustomException e) {
            System.err.println(e.getMessage());
        }
    }
}

